package com.synfusion.attendance.online

/**
 * Data class representing a Conversation between two users in Firestore `conversations/{conversationId}`.
 * Conversation ID is deterministically generated by sorting participant UIDs: `min(uid1, uid2)_max(uid1, uid2)`.
 */
data class FirestoreConversation(
    val id: String = "",
    val participants: List<String> = emptyList(),
    val lastMessage: String = "",
    val lastSenderUid: String = "",
    val lastTimestamp: Long = System.currentTimeMillis(),
    val unreadCounts: Map<String, Int> = emptyMap(),
    val createdAt: Long = System.currentTimeMillis(),
    val updatedAt: Long = System.currentTimeMillis()
)

/**
 * Delivery / Read status for a message.
 */
enum class MessageStatus {
    PENDING,
    SENT,       // Single Grey Tick: Committed to Firestore
    DELIVERED,  // Double Grey Tick: Recipient device acknowledged
    READ        // Double Blue Tick: Recipient read message
}

/**
 * Data class representing an individual Chat Message in `conversations/{conversationId}/messages/{messageId}`.
 */
data class FirestoreChatMessage(
    val id: String = "",
    val conversationId: String = "",
    val senderUid: String = "",
    val recipientUid: String = "",
    val text: String = "",
    val timestamp: Long = System.currentTimeMillis(),
    val status: MessageStatus = MessageStatus.SENT,
    val deliveredAt: Long? = null,
    val readAt: Long? = null
)

/**
 * Data class representing a Block record in `blocks/{blockerUid}_${blockedUid}`.
 */
data class BlockRecord(
    val blockerUid: String = "",
    val blockedUid: String = "",
    val timestamp: Long = System.currentTimeMillis()
)

/**
 * Data class representing a User Report submission in `reports/{reportId}`.
 */
data class ReportRecord(
    val id: String = "",
    val reporterUid: String = "",
    val targetUid: String = "",
    val reason: String = "",
    val details: String = "",
    val timestamp: Long = System.currentTimeMillis()
)
